WITH sales_by_month AS (SELECT hd.hd_demo_sk, hd.hd_income_band_sk, i.i_category, date_trunc('month', date_add('day', ws.ws_sold_date_sk, DATE '1970-01-01')) AS sale_month, SUM(ws.ws_net_profit) AS month_profit FROM web_sales ws INNER JOIN household_demographics hd ON ws.ws_bill_hdemo_sk = hd.hd_demo_sk INNER JOIN item i ON ws.ws_item_sk = i.i_item_sk GROUP BY hd.hd_demo_sk, hd.hd_income_band_sk, i.i_category, date_trunc('month', date_add('day', ws.ws_sold_date_sk, DATE '1970-01-01'))) SELECT hd_demo_sk, hd_income_band_sk, i_category, sale_month, month_profit, RANK() OVER (PARTITION BY i_category ORDER BY month_profit DESC) AS category_rank, CASE WHEN month_profit < 2000 THEN 'Below Target' ELSE 'Above Target' END AS target_flag FROM sales_by_month WHERE month_profit IS NOT NULL ORDER BY i_category, month_profit DESC
